// One row per job. The Actor already returns only postings that are new
// for this stateKey, so this only guards against duplicates inside a run.
const seen = new Set();
const rows = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const key = [j.vendor, j.company, j.jobId || j.url].join('|');
  if (!key || seen.has(key)) continue;
  seen.add(key);

  const salary =
    j.salaryRaw ||
    [j.salaryMin, j.salaryMax]
      .filter((v) => v !== null && v !== undefined && v !== '')
      .join(' - ');

  rows.push({
    json: {
      job_id: j.jobId || '',
      company: j.company || '',
      title: j.title || '',
      location: j.location || '',
      department: j.department || '',
      employment_type: j.employmentType || '',
      remote: j.remote === true ? 'yes' : j.remote === false ? 'no' : '',
      posted_at: j.postedAt || '',
      salary: salary || '',
      url: j.url || '',
      ats: j.vendor || '',
      first_seen: new Date().toISOString(),
    },
  });
}

return rows;

// Build one short digest so Slack/Telegram get a single message per run.
const rows = $input.all().map((i) => i.json).filter((r) => r && r.title);
if (!rows.length) return [];

const shown = rows.slice(0, 15);
const lines = shown.map(
  (r) => `- ${r.title} | ${r.company} | ${r.location || 'n/a'}\n  ${r.url}`,
);
const more =
  rows.length > shown.length
    ? `\n...and ${rows.length - shown.length} more rows in Google Sheets.`
    : '';

return [
  {
    json: {
      count: rows.length,
      text: `${rows.length} new job posting(s)\n\n${lines.join('\n')}${more}`,
    },
  },
];
